files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.quiz-card {
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 8px;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 0 rgba(0,0,0,0.3);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  color: var(--accent);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.question {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 24px;
  min-height: 2.5rem;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.pixel-btn {
  font-family: var(--font);
  font-size: 1.125rem;
  font-weight: 700;
  padding: 12px 24px;
  min-width: 80px;
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--border);
  border-radius: 4px;
  cursor: pointer;
  transition: transform 0.1s, box-shadow 0.1s, background 0.1s;
  box-shadow: 0 4px 0 var(--border);
}

.pixel-btn:hover:not(:disabled) {
  background: #ff5a75;
  transform: translateY(-2px);
  box-shadow: 0 6px 0 var(--border);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.pixel-btn:active:not(:disabled) {
  transform: translateY(2px);
  box-shadow: 0 2px 0 var(--border);
}

.pixel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: 0 4px 0 var(--border);
}

.score-line {
  font-size: 1.125rem;
  margin-bottom: 24px;
  color: var(--muted);
}

.score-line span {
  font-weight: 700;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.controls .pixel-btn {
  background: var(--border);
  color: var(--text);
  box-shadow: 0 4px 0 #0a1a2e;
}

.controls .pixel-btn:hover:not(:disabled) {
  background: #1a4a7a;
  box-shadow: 0 6px 0 #0a1a2e;
}

.controls .pixel-btn:active:not(:disabled) {
  box-shadow: 0 2px 0 #0a1a2e;
}

@media (max-width: 360px) {
  .quiz-card { padding: 24px 16px; }
  .question { font-size: 1.5rem; }
  .answers { gap: 12px; }
  .pixel-btn { padding: 10px 18px; font-size: 1rem; }
}

(function () {
  'use strict';

  var questionEl = document.getElementById('question');
  var answerA = document.getElementById('answer-a');
  var answerB = document.getElementById('answer-b');
  var scoreEl = document.getElementById('score');
  var nextBtn = document.getElementById('next');
  var restartBtn = document.getElementById('restart');

  var questions = [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ];

  var current = 0;
  var score = 0;
  var answered = false;
  var finished = false;

  function render() {
    var q = questions[current];
    questionEl.textContent = q.text;
    answerA.textContent = q.a;
    answerB.textContent = q.b;
    answerA.setAttribute('aria-label', 'Answer A: ' + q.a);
    answerB.setAttribute('aria-label', 'Answer B: ' + q.b);
    answerA.disabled = false;
    answerB.disabled = false;
    answered = false;
    finished = false;
    nextBtn.disabled = false;
    scoreEl.textContent = String(score);
  }

  function handleAnswer(choice) {
    if (answered || finished) return;
    answered = true;
    answerA.disabled = true;
    answerB.disabled = true;
    if (choice === questions[current].correct) {
      score += 1;
      scoreEl.textContent = String(score);
    }
  }

  function handleNext() {
    if (!answered && !finished) return;
    if (finished) return;
    if (current < questions.length - 1) {
      current += 1;
      render();
    } else {
      finished = true;
      questionEl.textContent = 'Finished';
      answerA.disabled = true;
      answerB.disabled = true;
      nextBtn.disabled = true;
    }
  }

  function handleRestart() {
    current = 0;
    score = 0;
    render();
  }

  answerA.addEventListener('click', function () { handleAnswer('a'); });
  answerB.addEventListener('click', function () { handleAnswer('b'); });
  nextBtn.addEventListener('click', handleNext);
  restartBtn.addEventListener('click', handleRestart);

  render();
})();
